 const dry=ctx.createGain(),master=ctx.createGain(),limiter=ctx.createDynamicsCompressor(),transport=ctx.createGain();dry.gain.value=.94;master.gain.value=volume*.72;limiter.threshold.value=-2.5;limiter.knee.value=2;limiter.ratio.value=12;limiter.attack.value=.001;limiter.release.value=.09;dry.connect(transport);transport.connect(master);master.connect(limiter);limiter.connect(destination);
 const roomIR=impulse(ctx,'room'),resIR=impulse(ctx,'strings'),room=ctx.createConvolver(),roomFilter=ctx.createBiquadFilter(),roomWet=ctx.createGain(),resonance=ctx.createConvolver(),resIn=ctx.createGain(),resOut=ctx.createGain(),resFilter=ctx.createBiquadFilter();room.normalize=false;room.buffer=roomIR;roomFilter.type='lowpass';roomFilter.frequency.value=5800;roomWet.gain.value=.095;roomFilter.connect(room);room.connect(roomWet);roomWet.connect(transport);resonance.normalize=false;resonance.buffer=resIR;resIn.gain.value=0;resOut.gain.value=0;resFilter.type='highpass';resFilter.frequency.value=90;resIn.connect(resonance);resonance.connect(resFilter);resFilter.connect(resOut);resOut.connect(transport);
 async function load(id){if(buffers.has(id))return buffers.get(id);if(pending.has(id))return pending.get(id);let task=(async()=>{const a=manifest.assets[id];if(!a)throw Error('音源が見つかりません: '+id);let bytes;if(window.PIANO_AUDIO_DATA?.[id]){let raw=atob(window.PIANO_AUDIO_DATA[id]),u=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)u[i]=raw.charCodeAt(i);bytes=u.buffer;}else{const response=await fetch(a.path,{cache:'force-cache'});if(!response.ok)throw Error('音源を読み込めません。配布HTMLまたはZIP内の音源を確認してください。');bytes=await response.arrayBuffer();}let buffer=await ctx.decodeAudioData(bytes);if(!buffer.length||!Number.isFinite(buffer.duration))throw Error('音源の変換に失敗しました: '+id);if(wanted.has(id))buffers.set(id,buffer);stats.loadedSamples=buffers.size;return buffer;})().finally(()=>pending.delete(id));pending.set(id,task);return task;}
 async function loadForSong(song,progress=()=>{}){let needed=new Set();for(const n of song.notes)for(const s of notePlan(n))needed.add(s.id);for(const ids of Object.values(manifest.mechanical))for(const id of ids)needed.add(id);wanted=needed;for(const id of buffers.keys())if(!wanted.has(id))buffers.delete(id);stats.loadedSamples=buffers.size;let list=[...needed],cursor=0,done=0;progress({loaded:0,total:list.length});await Promise.all(Array.from({length:3},async()=>{while(cursor<list.length){const id=list[cursor++];await load(id);progress({loaded:++done,total:list.length});}}));return list.length;}
 function route(gain,withResonance=true){gain.connect(dry);gain.connect(roomFilter);if(withResonance)gain.connect(resIn);}
 function noise(id,when,amp,rate=1){let buffer=buffers.get(id);if(!buffer)return;const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;source.playbackRate.value=rate;gain.gain.value=amp;source.connect(gain);route(gain,false);const item={source,gain};auxiliary.add(item);source.onended=()=>{auxiliary.delete(item);source.disconnect();gain.disconnect();};source.start(when);source.stop(when+buffer.duration/rate);}
 function fadeVoice(v,when){let t=v.n[0]+(when-v.when)*v.speed,level=PianoPedal.levelAt(v.profile,t);v.gain.gain.cancelScheduledValues(when);v.gain.gain.setValueAtTime(Math.max(1e-7,v.amp*level),when);v.gain.gain.linearRampToValueAtTime(0,when+.040);for(const source of v.sources)try{source.stop(when+.045);}catch{}v.stopAt=when+.045;}
 function startNote(song,n,when,speed=1){const plan=notePlan(n),duration=Math.max(...plan.map(s=>{const b=buffers.get(s.id);if(!b)throw Error('ピアノ音源の準備が完了していません。');return b.duration/s.rate;})),profile=dampingEnvelope(song,n,speed,duration),gain=ctx.createGain(),amp=.85*(n[3]/127)**1.15,sources=[];
 gain.gain.setValueAtTime(0,when);gain.gain.linearRampToValueAtTime(amp,when+.002);for(const point of profile.points.slice(2))gain.gain.exponentialRampToValueAtTime(Math.max(1e-7,amp*point.level),when+(point.t-n[0])/speed);route(gain);
 const live=[...voices].filter(v=>v.stopAt>when+.050),same=live.filter(v=>v.n[2]===n[2]&&v.when<when-.000001).sort((a,b)=>a.when-b.when);for(const v of same.slice(0,Math.max(0,same.length-1)))fadeVoice(v,when);if(live.length>=128){let old=live.reduce((a,b)=>a.amp*Math.exp(-(when-a.when)/3)<b.amp*Math.exp(-(when-b.when)/3)?a:b);fadeVoice(old,when);}
 const voice={sources,gain,n,profile,when,speed,amp,stopAt:when+(profile.stop-n[0])/speed+.005};voices.add(voice);let active=plan.length;for(const s of plan){const source=ctx.createBufferSource(),balance=ctx.createGain();source.buffer=buffers.get(s.id);source.playbackRate.value=s.rate;balance.gain.value=s.weight;source.connect(balance);balance.connect(gain);sources.push(source);source.onended=()=>{source.disconnect();balance.disconnect();if(--active===0){voices.delete(voice);gain.disconnect();}};source.start(when);source.stop(Math.max(when+.004,Math.min(when+source.buffer.duration/s.rate,when+(profile.stop-n[0])/speed+.005)));}
 const releases=manifest.mechanical.keyRelease,register=clamp(Math.floor((n[2]-21)/24),0,releases.length-1),releaseTime=when+(profile.keyEnd-n[0])/speed;if(releaseTime>=when)noise(releases[register],releaseTime,.014*(n[3]/127)**.6,1+Math.sin(n[0]*17+n[2])*.008);
 stats.attacks.push({pitch:n[2],velocity:n[3],when,sources:plan.map(s=>({id:s.id,root:s.root,rate:s.rate,weight:s.weight,layer:s.layer}))});if(stats.attacks.length>512)stats.attacks.shift();return voice;
 }
 function startTransport(song,start,anchor,speed=1){const now=ctx.currentTime;transport.gain.cancelScheduledValues(now);transport.gain.setValueAtTime(0,now);transport.gain.linearRampToValueAtTime(1,Math.max(now+.01,anchor));let depth=pedalAt(song,start);resIn.gain.cancelScheduledValues(now);resOut.gain.cancelScheduledValues(now);resIn.gain.setValueAtTime(depth,anchor);resOut.gain.setValueAtTime(.032*depth,anchor);
 for(let i=0;i<song.pedals.length;i++){let p=song.pedals[i];if(p[0]<=start)continue;let when=anchor+(p[0]-start)/speed,value=p[1]/127;resIn.gain.setValueAtTime(depth,when);resIn.gain.linearRampToValueAtTime(value,when+.015);resOut.gain.setValueAtTime(.032*depth,when);resOut.gain.linearRampToValueAtTime(.032*value,when+.045);if((depth>=.5)!==(value>=.5)){let ids=value>=.5?manifest.mechanical.pedalDown:manifest.mechanical.pedalUp;noise(ids[i%ids.length],when,.020);}depth=value;}
 }
